CREATE TABLE "public"."services" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name"       text                     NOT NULL,
  "price"      numeric                  NOT NULL DEFAULT 0,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "is_favorite" boolean                  NOT NULL DEFAULT false,
  CONSTRAINT "services_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."services"
  ENABLE ROW LEVEL SECURITY;

CREATE POLICY "services_all_staff" ON "public"."services"
  FOR ALL
  TO PUBLIC
  USING ((public.current_role_name() IS NOT NULL))
  WITH CHECK ((public.current_role_name() IS NOT NULL));

REVOKE ALL ON SEQUENCE "public"."services_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."services_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."services_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."services_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."services_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."services_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."services_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."services_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."services" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."services" TO "service_role";

REVOKE ALL ON TABLE "public"."services" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."services" TO "postgres";
